/// Combat text, tuned per weapon style and per creature kind.
enum EnemyKind { bug, beast, pale, birds, sludge, golem, worm, machine, human, brute }

EnemyKind enemyKind(EnemyType t) {
  switch (t) {
    case EnemyType.skitter: return EnemyKind.bug;
    case EnemyType.hound: return EnemyKind.beast;
    case EnemyType.crawler: return EnemyKind.pale;
    case EnemyType.lurker: return EnemyKind.pale;
    case EnemyType.swarm: return EnemyKind.birds;
    case EnemyType.spitter: return EnemyKind.sludge;
    case EnemyType.colossus: return EnemyKind.golem;
    case EnemyType.wyrm: return EnemyKind.worm;
    case EnemyType.sentry: return EnemyKind.machine;
    case EnemyType.warmachine: return EnemyKind.machine;
    case EnemyType.brute: return EnemyKind.brute;
    case EnemyType.raider: return EnemyKind.human;
    case EnemyType.captain: return EnemyKind.human;
    case EnemyType.straggler: return EnemyKind.human;
  }
}

