  static String _style(String w) => w == 'rifle' ? 'rifle' : (w == 'cutter' ? 'cutter' : 'melee');

  static String playerHit(Random r, String weapon, EnemyKind kind) {
    final k = kind.name, w = _weaponNoun.containsKey(weapon) ? weapon : 'pipe';
    final slots = <String, List<String>>{
      'windup': _windup, 'shotopen': _shotopen, 'cutopen': _cutopen,
      'weapon': _weaponNoun[w]!, 'strike': _strike[w]!, 'part': _part[k]!, 'react': _react[k]!,
    };
    final t = _style(w) == 'rifle' ? _hitRifle : (_style(w) == 'cutter' ? _hitCut : _hitMelee);
    return Gen.from(t, r, slots);
  }

  static String playerMiss(Random r, String weapon, EnemyKind kind, String n) {
    final k = kind.name;
    final slots = <String, List<String>>{
      'miss_melee': _missMelee, 'miss_ranged': _missRanged, 'miss_cutter': _missCutter, 'dodge': _dodge[k]!,
    };
    final s = _style(weapon);
    final t = s == 'rifle'
        ? ['{miss_ranged}', '{miss_ranged} The {n} {dodge}.']
        : (s == 'cutter' ? ['{miss_cutter}', '{miss_cutter} The {n} {dodge}.'] : ['{miss_melee}', '{miss_melee} The {n} {dodge}.']);
    return Gen.from(t, r, slots).replaceAll('{n}', n);
  }

  static String enemyMiss(Random r, EnemyKind kind, String n) =>
      'The $n ${_missverb[kind.name]![r.nextInt(_missverb[kind.name]!.length)]}.';

  static String enemyHit(Random r, EnemyKind kind, String n) {
    final slots = <String, List<String>>{'attack': _attack[kind.name]!, 'bodypart': _bodypart, 'pain': _pain};
    return Gen.from(_hitEnemy, r, slots).replaceAll('{n}', n);
  }

  static String death(Random r, EnemyKind kind, String n) {
    final d = _die[kind.name]!;
    final line = d[r.nextInt(d.length)].replaceAll('{n}', n);
    return r.nextDouble() < 0.5 ? '$line ${_afterFight[r.nextInt(_afterFight.length)]}' : line;
  }

  static String crit(Random r) => _crit[r.nextInt(_crit.length)];
  static String stim(Random r) => _stim[r.nextInt(_stim.length)];
  static String defend(Random r) => _defend[r.nextInt(_defend.length)];
  static String escapeOk(Random r) => _escapeOk[r.nextInt(_escapeOk.length)];
  static String escapeFail(Random r) => _escapeFail[r.nextInt(_escapeFail.length)];
  static String quip(Random r) => _quips[r.nextInt(_quips.length)];
